export class UserResourceService {
  private readonly userApiUrl = "/users/v2";
  private readonly permissionsApiUrl = "/users/v2/permissions";

  constructor(private readonly request: Request) {}

  async createUser(userPayload: UserCreatePayload) {
    const createResponse = await this.request.post(this.userApiUrl, userPayload);
    if (!createResponse.ok) throw new Error("User creation failed");

    const userId = createResponse.json()!.id;
    // Return the user data along with the ID for further operations
    return {
      user: createResponse.json(),
      userId,
    };
  }

  async assignPermissions(userId: string, permissionPayload: PermissionPayload) {
    // Optionally, you can validate userId here if needed
    const permissionsPayload = {
      ...permissionPayload,
      id: userId,
    };
    const permissionsResponse = await this.request.post(this.permissionsApiUrl, permissionsPayload);
    if (!permissionsResponse.ok) throw new Error("Permission assignment failed");

    // Optionally return the result or just confirm success
    return permissionsResponse.json();
  }
}

